namespace ghidra.feature.vt.gui.wizard.add;





using docking.wizard;
using ghidra.feature.vt.api.main;
using ghidra.feature.vt.api.main;
using ghidra.util;

/**
 * Wizard step for choosing which correlators to run when adding to an existing version
 * tracking session.
 */
public class CorrelatorChooserStep : WizardStep<AddToSessionData> {
	private CorrelatorChooserPanel panel;

	public CorrelatorChooserStep(VTAddToSessionWizardModel model, VTSession session) : base(model, "Select Correlation Algorithm(s)",
			new HelpLocation("VersionTrackingPlugin", "Correlator_Panel"))
    {

		panel = new CorrelatorChooserPanel(session, this.notifyStatusChanged);
	}

	/* @Override */
	public void initialize(AddToSessionData data) {
		// nothing to do
	}

	/* @Override */
	public bool isValid() {
		List<VTProgramCorrelatorFactory> correlators = panel.getSelectedCorrelators();
		if (!correlators.isEmpty()) {
			return true;
		}
		return false;
	}

	/* @Override */
	public void populateData(AddToSessionData data) {
		data.setCorrelators(panel.getSelectedCorrelators());
	}

	/* @Override */
	public bool apply(AddToSessionData data) {
		return true;
	}

	/* @Override */
	public JComponent getComponent() {
		return panel;
	}

	/* @Override */
	public bool canFinish(AddToSessionData data) {
		return data.getCorrelators() != null;
	}

}
